from __future__ import annotations

from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, OptionalNullable, SdkBaseModel
from .destination_details import DestinationDetails, DestinationDetailsDict
from .money import Money, MoneyDict
from .processing_fee import ProcessingFee, ProcessingFeeDict


class PaymentRefund(SdkBaseModel):
    """Represents a refund of a payment made using Square. Contains information about the original payment and the
    amount of money refunded."""

    id: str
    """The unique ID for this refund, generated by Square."""

    status: OptionalNullable[str] = UNSET
    """The refund's status:
    - ``PENDING`` - Awaiting approval.
    - ``COMPLETED`` - Successfully completed.
    - ``REJECTED`` - The refund was rejected.
    - ``FAILED`` - An error occurred."""

    location_id: OptionalNullable[str] = UNSET
    """The location ID associated with the payment this refund is attached to."""

    unlinked: Optional[bool] = UNSET
    """Flag indicating whether or not the refund is linked to an existing payment in Square."""

    destination_type: OptionalNullable[str] = UNSET
    """The destination type for this refund.

    Current values include ``CARD``, ``BANK_ACCOUNT``, ``WALLET``, ``BUY_NOW_PAY_LATER``, ``CASH``, ``EXTERNAL``, and
    ``SQUARE_ACCOUNT``."""

    destination_details: Optional[DestinationDetails] = UNSET
    """Details about a refund's destination."""

    amount_money: Money
    """Represents an amount of money. ``Money`` fields can be signed or unsigned. Fields that do not explicitly define
    whether they are signed or unsigned are considered unsigned and can only hold positive amounts. For signed fields,
    the sign of the value indicates the purpose of the money transfer. See `Working with Monetary Amounts
    <https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts>`__ for more information."""

    app_fee_money: Optional[Money] = UNSET
    """Represents an amount of money. ``Money`` fields can be signed or unsigned. Fields that do not explicitly define
    whether they are signed or unsigned are considered unsigned and can only hold positive amounts. For signed fields,
    the sign of the value indicates the purpose of the money transfer. See `Working with Monetary Amounts
    <https://developer.squareup.com/docs/build-basics/working-with-monetary-amounts>`__ for more information."""

    processing_fee: OptionalNullable[list[ProcessingFee]] = UNSET
    """Processing fees and fee adjustments assessed by Square for this refund."""

    payment_id: OptionalNullable[str] = UNSET
    """The ID of the payment associated with this refund."""

    order_id: OptionalNullable[str] = UNSET
    """The ID of the order associated with the refund."""

    reason: OptionalNullable[str] = UNSET
    """The reason for the refund."""

    created_at: Optional[str] = UNSET
    """The timestamp of when the refund was created, in RFC 3339 format."""

    updated_at: Optional[str] = UNSET
    """The timestamp of when the refund was last updated, in RFC 3339 format."""

    team_member_id: Optional[str] = UNSET
    """An optional ID of the team member associated with taking the payment."""

    terminal_refund_id: Optional[str] = UNSET
    """An optional ID for a Terminal refund."""


class PaymentRefundDict(TypedDict):
    id: str
    status: NotRequired[str | None]
    location_id: NotRequired[str | None]
    unlinked: NotRequired[bool]
    destination_type: NotRequired[str | None]
    destination_details: NotRequired[DestinationDetailsDict]
    amount_money: MoneyDict
    app_fee_money: NotRequired[MoneyDict]
    processing_fee: NotRequired[list[ProcessingFeeDict] | None]
    payment_id: NotRequired[str | None]
    order_id: NotRequired[str | None]
    reason: NotRequired[str | None]
    created_at: NotRequired[str]
    updated_at: NotRequired[str]
    team_member_id: NotRequired[str]
    terminal_refund_id: NotRequired[str]
